import numpy as np
import cv2
import json
from Src.analysis.analysis_io import atomic_json
from vispy import scene, app
from vispy.scene.visuals import Arrow
import os
from scipy.spatial.transform import Rotation
from scipy.signal import savgol_filter 

class Triangulate3DViewer:
    def __init__(self, K_L, K_R, F, extrinsics_path=None, swap_inputs=False):
        # swap_inputs：呼叫端送進來的第一支是正面 CF 時設 True，內部先對調成「L＝側面」再三角化，
        # 讓 3D 座標維持學姊原本的側面相機座標（預設視角、地面與舊 3D 檔都以此為準）
        self.swap_inputs = swap_inputs
        # self.json_path_L = json_path_L
        # self.json_path_R = json_path_R
        self.K_L = K_L
        self.K_R = K_R
        self.F = F
        
        # 外參相關變量
        self.R_ext = None  # 旋轉矩陣
        self.t_ext = None  # 平移向量
        self.use_extrinsics = False  # 是否使用外參
        
        # 加載外參（如果指定了）
        if extrinsics_path:
            self.load_extrinsics(extrinsics_path)

        self.head_links = [[0, 1], [0, 2], [1, 3], [2, 4]]
        self.left_links = [[5, 18], [5, 7], [7, 9], [19, 11], [11, 13], [13, 24]]
        self.right_links = [[6, 18], [6, 8], [8, 10], [19, 12], [12, 14], [14, 25]]
        self.trunk_links = [[17, 18], [18, 19]]

        self.all_3d_frames = {}
        self.frame_idx = 0
        self.x_range = self.y_range = self.z_range = (0, 1)

        self.canvas = scene.SceneCanvas(keys='interactive', show=False, bgcolor='white')
        self.view = self.canvas.central_widget.add_view()
        self.view.camera = scene.cameras.TurntableCamera(fov=45, azimuth=110, elevation=0, up='-y', distance=0.21)
        axis = scene.visuals.XYZAxis(parent=self.view.scene)
        axis.transform = scene.transforms.STTransform(scale=(0.01, 0.01, 0.01))
        self.y_axis_arrow = Arrow(color='orange', width=2, parent=self.view.scene)
        self.plane_normal_arrow = Arrow(color='magenta', width=2, parent=self.view.scene)

        self.scatter = scene.visuals.Markers(parent=self.view.scene)
        self.head_lines = scene.visuals.Line(connect='segments', color='orange', width=2, parent=self.view.scene)
        self.left_lines = scene.visuals.Line(connect='segments', color='red', width=2, parent=self.view.scene)
        self.right_lines = scene.visuals.Line(connect='segments', color='blue', width=2, parent=self.view.scene)
        self.trunk_lines = scene.visuals.Line(connect='segments', color='orange', width=2, parent=self.view.scene)

        self.timer = app.Timer(interval=0.2, connect=self.update, start=False)

        self.save_json_path = "all_3d_frames.json"  # 儲存 json 的路徑
        self.auto_save = True  # 控制是否自動存檔
        self.auto_save_interval = 30  # 每 N 幀才自動存一次，避免每幀重寫整份 JSON
        self.range_update_interval = 5  # 每 N 幀更新一次相機範圍，降低全量統計頻率
        self.auto_fit_camera_each_update = False  # False: 只在初次資料可用時自動對焦一次
        self._camera_range_initialized = False
        self._last_saved_frame = -1

        self.arm_plane_mesh = scene.visuals.Mesh(
            vertices=np.zeros((3, 3)), 
            faces=np.array([[0, 1, 2]]), 
            color=(0, 1, 1, 0.3), # 青色，半透明
            parent=self.view.scene # 確保加入到你的場景 view 中
        )

        # self.load_and_triangulate()

    def load_extrinsics(self, extrinsics_path):
        """加載你標定的外參 JSON 檔案
        
        Args:
            extrinsics_path: extrinsics.json 的路徑
        """
        try:
            with open(extrinsics_path, 'r') as f:
                ext_data = json.load(f)
            
            # 從 JSON 中讀取上下面的外參
            # 假設前相機 (K_L) 為右相機，上相機 (K_R) 為上相機
            self.R_ext = np.array(ext_data['rotation_matrix_front'])
            self.t_ext = np.array(ext_data['translation_vector_front']).reshape(3, 1)
            
            self.use_extrinsics = True
            print(f"[成功] 已加載外參檔: {extrinsics_path}")
            print(f"  旋轉矩陣 shape: {self.R_ext.shape}")
            print(f"  平移向量 shape: {self.t_ext.shape}")
        except Exception as e:
            print(f"[錯誤] 加載外參失敗: {e}")
            self.use_extrinsics = False

    def setJsonPaths(self, folder_path: str, file_name: str):
        if file_name is not None:
            self.save_json_path = os.path.join(folder_path, f"{file_name}_3D.json")

    def draw_ground_from_first_frame(self):
        if not self.all_3d_frames:
            return

        # Use the earliest available frame key instead of assuming frame 1 exists.
        first_frame_key = min(self.all_3d_frames.keys())
        first_frame = self.all_3d_frames.get(first_frame_key)
        if first_frame is None or len(first_frame) == 0:
            return
        # 取第一幀骨架的最低點 (腳的位置)
        ground_y = np.max(first_frame[:, 1])

        # 畫一個長方形平面 (X-Z 範圍根據骨架自動調整)
        x_min, x_max = np.min(first_frame[:, 0]), np.max(first_frame[:, 0])
        z_min, z_max = np.min(first_frame[:, 2]), np.max(first_frame[:, 2])

        xx, zz = np.meshgrid(
            np.linspace(x_min - 0.05, x_max + 0.2),
            np.linspace(z_min - 0.05, z_max + 0.05)
        )
        yy = np.full_like(xx, ground_y)

        # 🚩 ground 保存在 self，不會被清掉
        self.ground = scene.visuals.SurfacePlot(
            xx, yy, zz,
            color=(0.5, 0.5, 0.5, 0.3), shading=None
        )
        self.view.add(self.ground)

    def draw_angle_on_xz_plane(self, frame_idx=None):
        if not self.all_3d_frames:
            return

        if frame_idx is None:
            frame_idx = self.frame_idx

        joints = self.all_3d_frames[frame_idx]
        
        # 使用你的關節索引
        left_shoulder = np.array(joints[5])
        right_shoulder = np.array(joints[6])
        left_hip = np.array(joints[11])
        right_hip = np.array(joints[12])

        # 1. 計算向量
        shoulder_line = right_shoulder - left_shoulder
        hip_line = right_hip - left_hip

        # 2. 投影到 XZ 平面
        shoulder_vector_xz = np.array([shoulder_line[0], 0, shoulder_line[2]])
        hip_vector_xz = np.array([hip_line[0], 0, hip_line[2]])

        # 3. 確定繪製起點 (例如，左右髖關節中點)
        origin_point = (left_hip + right_hip) / 2
        
        # 移除舊的視覺元素
        # 你可能需要為這些元素新增實例變數，以便後續刪除
        if hasattr(self, 'xz_angle_lines'):
            for line in self.xz_angle_lines:
                line.parent = None
        if hasattr(self, 'xz_angle_label'):
            self.xz_angle_label.parent = None
        self.xz_angle_lines = []
        
        # 4. 繪製投影向量
        shoulder_proj_line = scene.visuals.Line(
            pos=np.array([left_hip, left_hip + shoulder_vector_xz]), 
            color="#F10CE2", width=3, parent=self.view.scene
        )
        hip_proj_line = scene.visuals.Line(
            pos=np.array([left_hip, left_hip + hip_vector_xz]),
            color="#650ABA", width=3, parent=self.view.scene
        )
        self.xz_angle_lines.extend([shoulder_proj_line, hip_proj_line])
        
        # 5. 計算夾角
        angle_deg = self.calculate_angle_between_shoulder_hip_lines(frame_idx)
        
        # 6. 繪製角度文字
        label_pos = origin_point + (shoulder_vector_xz + hip_vector_xz) / 2
        self.xz_angle_label = scene.visuals.Text(
            f"{angle_deg:.2f}°", 
            color='black', font_size=1, pos=label_pos, parent=self.view.scene
        )

    def _auto_save_3d_frames(self):
        if not self.auto_save or not self.all_3d_frames:
            return

        latest_frame = max(self.all_3d_frames.keys())
        if self._last_saved_frame >= 0 and (latest_frame - self._last_saved_frame) < self.auto_save_interval:
            return

        self.save_to_json()
        self._last_saved_frame = latest_frame

    def save_to_json(self, path=None):
        """Manually trigger saving 3D coordinates to JSON."""
        if not self.all_3d_frames:
            return
            
        target_path = path if path else self.save_json_path
        data_to_save = []
        sorted_frame_indices = sorted(self.all_3d_frames.keys())
        for idx in sorted_frame_indices:
            frame_data = self.all_3d_frames[idx] # 取出該幀的 3D 點
            
            # 每個點補齊 [x, y, z] 格式
            keypoints = [[float(x), float(y), float(z)] for x, y, z in frame_data]

            data_to_save.append({
                "keypoints": keypoints,
                "frame_number": idx  # 使用真實的 frame index
            })

        atomic_json(target_path, data_to_save)
        print(f"[Info] 3D coordinates saved to {target_path} (Total frames: {len(data_to_save)})")

    def compute_essential_matrix(self):
        E = self.K_R.T @ self.F @ self.K_L
        U, _, Vt = np.linalg.svd(E)
        S = [1, 1, 0]
        return U @ np.diag(S) @ Vt

    def decompose_essential_matrix(self, E):
        U, _, Vt = np.linalg.svd(E)
        if np.linalg.det(U @ Vt) < 0:
            Vt = -Vt
        W = np.array([[0, -1, 0], [1, 0, 0], [0, 0, 1]])
        R1 = U @ W @ Vt
        R2 = U @ W.T @ Vt
        t = U[:, 2]
        return [(R1, t), (R1, -t), (R2, t), (R2, -t)]

    def load_and_triangulate(self):
        with open(self.json_path_L) as f:
            data_L = json.load(f)
        with open(self.json_path_R) as f:
            data_R = json.load(f)
        if self.swap_inputs:
            data_L, data_R = data_R, data_L

        E = self.compute_essential_matrix()
        poses = self.decompose_essential_matrix(E)
        P1 = self.K_L @ np.hstack((np.eye(3), np.zeros((3, 1))))

        for frame_L, frame_R in zip(data_L, data_R):
            # 🚩 優先使用平滑後的點 (smoothed_keypoints) 進行 3D 重建
            pts_L = frame_L.get("smoothed_keypoints", frame_L["keypoints"])
            pts_R = frame_R.get("smoothed_keypoints", frame_R["keypoints"])
            # pts_L = frame_L.get("keypoints", frame_L["keypoints"])
            # pts_R = frame_R.get("keypoints", frame_R["keypoints"])
            
            kp_L = np.array(pts_L)[:, :2].T
            kp_R = np.array(pts_R)[:, :2].T
            if kp_L.shape[1] != 26 or kp_R.shape[1] != 26:
                continue

            best_3d = None
            max_in_front = -1
            for R, t in poses:
                P2 = self.K_R @ np.hstack((R, t.reshape(3, 1)))
                pts4d_h = cv2.triangulatePoints(P1, P2, kp_L, kp_R)
                pts3d = (pts4d_h[:3] / pts4d_h[3]).T
                z1 = pts3d[:, 2]
                z2 = (R @ pts3d.T + t.reshape(3, 1))[2, :]
                in_front = np.sum((z1 > 0) & (z2 > 0))
                if in_front > max_in_front:
                    best_3d = pts3d
                    max_in_front = in_front
            if best_3d is not None:
                self.all_3d_frames.append(best_3d)
                self._auto_save_3d_frames()  # 自動存檔

        if self.all_3d_frames:
            all_pts = np.concatenate(self.all_3d_frames, axis=0)
            self.x_range = tuple(np.percentile(all_pts[:, 0], [2, 98]))
            self.y_range = tuple(np.percentile(all_pts[:, 1], [2, 98]))
            self.z_range = tuple(np.percentile(all_pts[:, 2], [2, 98]))
            if (not self._camera_range_initialized) or self.auto_fit_camera_each_update:
                self.view.camera.set_range(
                    x=(self.x_range[0] - 0.1, self.x_range[1] + 0.1),
                    y=(self.y_range[0] - 0.1, self.y_range[1] + 0.1),
                    z=(self.z_range[0] - 0.1, self.z_range[1] + 0.1)
                )
                self._camera_range_initialized = True

    def add_2d_keypoints(self, frame_L, frame_R, frame_num:int):
        if frame_num in self.all_3d_frames:
            self.frame_idx = frame_num
            self.update()
            # print(f"Frame {frame_num} 已經存在，跳過計算 (或更新)。")
            return
        # frame_L, frame_R: dict, 需有 "keypoints" 欄位
        if self.swap_inputs:
            frame_L, frame_R = frame_R, frame_L
        kp_L = np.array(frame_L["keypoints"])[:, :2].T
        kp_R = np.array(frame_R["keypoints"])[:, :2].T
        if kp_L.shape[1] != 26 or kp_R.shape[1] != 26:
            print(f'Invalid keypoints shape: {kp_L.shape}, {kp_R.shape}')
            return

        # 根據是否使用外參或依 Essential Matrix 計算
        if self.use_extrinsics and self.R_ext is not None and self.t_ext is not None:
            # 使用你標定的外參直接進行三角測量
            P1 = self.K_L @ np.hstack((np.eye(3), np.zeros((3, 1))))
            P2 = self.K_R @ np.hstack((self.R_ext, self.t_ext))
            
            pts4d_h = cv2.triangulatePoints(P1, P2, kp_L, kp_R)
            best_3d = (pts4d_h[:3] / pts4d_h[3]).T
            
            if best_3d is not None:
                self.all_3d_frames[frame_num] = best_3d
                self.frame_idx = frame_num
                if (not self._camera_range_initialized) or (len(self.all_3d_frames) % self.range_update_interval == 0):
                    self.update_ranges()
                self.update()
                # self._auto_save_3d_frames()  # 自動存檔
        else:
            # 原始方法：從 Essential Matrix 分解並篩選
            E = self.compute_essential_matrix()
            poses = self.decompose_essential_matrix(E)
            P1 = self.K_L @ np.hstack((np.eye(3), np.zeros((3, 1))))

            best_3d = None
            max_in_front = -1
            for R, t in poses:
                P2 = self.K_R @ np.hstack((R, t.reshape(3, 1)))
                pts4d_h = cv2.triangulatePoints(P1, P2, kp_L, kp_R)
                pts3d = (pts4d_h[:3] / pts4d_h[3]).T
                z1 = pts3d[:, 2]
                z2 = (R @ pts3d.T + t.reshape(3, 1))[2, :]
                in_front = np.sum((z1 > 0) & (z2 > 0))
                if in_front > max_in_front:
                    best_3d = pts3d
                    max_in_front = in_front
            if best_3d is not None:
                self.all_3d_frames[frame_num] = best_3d
                self.frame_idx = frame_num
                if (not self._camera_range_initialized) or (len(self.all_3d_frames) % self.range_update_interval == 0):
                    self.update_ranges()
                self.update()
                # self._auto_save_3d_frames()  # 自動存檔
        
        # 🚩 只在第一幀時呼叫，建立地面
        if self.all_3d_frames and frame_num == min(self.all_3d_frames.keys()): # ✅ 新寫法：確保它是字典中最小的 Key
             self.draw_ground_from_first_frame()

    def update_ranges(self):
        if self.all_3d_frames:
            all_pts = np.concatenate(list(self.all_3d_frames.values()), axis=0)
            self.x_range = tuple(np.percentile(all_pts[:, 0], [2, 98]))
            self.y_range = tuple(np.percentile(all_pts[:, 1], [2, 98]))
            self.z_range = tuple(np.percentile(all_pts[:, 2], [2, 98]))
            if (not self._camera_range_initialized) or self.auto_fit_camera_each_update:
                self.view.camera.set_range(
                    x=(self.x_range[0] - 0.05, self.x_range[1] + 0.05),
                    y=(self.y_range[0] - 0.05, self.y_range[1] + 0.05),
                    z=(self.z_range[0] - 0.05, self.z_range[1] + 0.05)
                )
                self._camera_range_initialized = True

    def get_skeleton_lines(self, points_3d):
        # 分別回傳四組骨架線
        def get_links(links):
            segs = []
            for (i, j) in links:
                if i < len(points_3d) and j < len(points_3d):
                    segs.append([points_3d[i], points_3d[j]])
            return np.array(segs)
        return (
            get_links(self.head_links),
            get_links(self.left_links),
            get_links(self.right_links),
            get_links(self.trunk_links)
        )
    
    def draw_plane_normal(self, frame_idx=None):
        if not self.all_3d_frames:
            return
        if frame_idx is None:
            frame_idx = self.frame_idx
        joints = self.all_3d_frames[frame_idx]
        shoulder = np.array(joints[6])
        elbow = np.array(joints[8])
        wrist = np.array(joints[10])
        neck = np.array(joints[18])      # 頸
        hip = np.array(joints[19])       # 臀

        upper = shoulder - elbow
        forearm = wrist - elbow
        plane_normal = np.cross(upper, forearm)

        if hasattr(self, 'arm_plane_mesh'):
            # 頂點數據：肩膀 -> 手肘 -> 手腕
            plane_vertices = np.array([shoulder, elbow, wrist])
            # 面數據：連接頂點 0, 1, 2 形成三角形
            plane_faces = np.array([[0, 1, 2]])
            
            # 更新 Mesh 數據
            # 注意：如果你的庫不支援動態更新 faces，通常只需更新 vertices 即可
            self.arm_plane_mesh.set_data(vertices=plane_vertices, faces=plane_faces)

        if np.linalg.norm(plane_normal) == 0:
            self.plane_normal_arrow.set_data(pos=np.array([[elbow, elbow]]))  # 不顯示
            if hasattr(self, 'arm_plane_mesh'):
                 self.arm_plane_mesh.set_data(vertices=np.zeros((3, 3))) 
            return
        plane_normal /= np.linalg.norm(plane_normal)

        # 從肘部出發，畫出法向量
        arrow_tip = elbow + plane_normal * 0.01  # 0.1 可依座標比例調整
        self.plane_normal_arrow.set_data(pos=np.array([elbow, arrow_tip]))

        # 畫y軸向量
        y_axis = hip - neck
        y_axis /= np.linalg.norm(y_axis)
        y_tip = elbow + y_axis * 0.01
        self.y_axis_arrow.set_data(pos=np.array([elbow, y_tip]))

    def update(self, event=None):
        if not self.all_3d_frames:
            return
        # 如果當前幀不在字典裡 (可能被清空或跳躍)，找一個最接近的
        if self.frame_idx not in self.all_3d_frames:
            valid_frames = sorted(self.all_3d_frames.keys())
            if not valid_frames: return
            self.frame_idx = valid_frames[0]

        points_3d = self.all_3d_frames[self.frame_idx]
        dist = np.linalg.norm(points_3d[19])
        real_dist = dist * 20.237 
        # print(f"臀部關節3d座標{points_3d[19]}")
        # print(f"臀部關節到世界原點(前相機光心)距離為: {dist:.3f}, 約 {real_dist:.3f} 米")
        # self.scatter.set_data(points_3d, face_color='orange', size=5)
        head_segs, left_segs, right_segs, trunk_segs = self.get_skeleton_lines(points_3d)
        self.head_lines.set_data(pos=head_segs.reshape(-1, 3), connect='segments')
        self.left_lines.set_data(pos=left_segs.reshape(-1, 3), connect='segments')
        self.right_lines.set_data(pos=right_segs.reshape(-1, 3), connect='segments')
        self.trunk_lines.set_data(pos=trunk_segs.reshape(-1, 3), connect='segments')
        # self.draw_plane_normal(self.frame_idx)
        # self.draw_angle_on_xz_plane(self.frame_idx)

    def set_frame(self, frame_idx):
        if frame_idx in self.all_3d_frames:
            self.frame_idx = frame_idx
            points_3d = self.all_3d_frames[frame_idx]
            # self.scatter.set_data(points_3d, face_color='orange', size=5)

            head_segs, left_segs, right_segs, trunk_segs = self.get_skeleton_lines(points_3d)
            self.head_lines.set_data(pos=head_segs.reshape(-1, 3), connect='segments')
            self.left_lines.set_data(pos=left_segs.reshape(-1, 3), connect='segments')
            self.right_lines.set_data(pos=right_segs.reshape(-1, 3), connect='segments')
            self.trunk_lines.set_data(pos=trunk_segs.reshape(-1, 3), connect='segments')
            # self.draw_plane_normal(frame_idx)
            # self.draw_angle_on_xz_plane(self.frame_idx)
            self.canvas.update()

    def get_canvas(self):
        return self.canvas

    def start(self):
        self.timer.start()

    def get_distance_between(self, idx1, idx2, frame_idx=None):
        """
        計算指定 frame 的 idx1 與 idx2 兩個 3D keypoint 之間的距離。
        若 frame_idx 為 None，則取目前 frame。
        """
        if not self.all_3d_frames:
            print("No 3D frames available.")
            return 0.0
        if frame_idx is None:
            frame_idx = self.frame_idx
            print(f"Using current frame index: {frame_idx}")
        if frame_idx not in self.all_3d_frames:
            # print(f"Invalid frame index: {frame_idx}. Must be between 0 and {len(self.all_3d_frames) - 1}.")
            return 0.0
        points_3d = self.all_3d_frames[frame_idx]
        if idx1 < 0 or idx2 < 0 or idx1 >= len(points_3d) or idx2 >= len(points_3d):
            # print(f"Invalid keypoint indices: {idx1}, {idx2}. Must be between 0 and {len(points_3d) - 1}.")
            return 0.0
        return np.linalg.norm(points_3d[idx1] - points_3d[idx2])

    def arm_cocking_angle(self, frame_idx=None):
        if not self.all_3d_frames:
            print("No 3D frames available.")
            return 0.0
        if frame_idx not in self.all_3d_frames:
            return 0.0

        joints = self.all_3d_frames[frame_idx]
        shoulder = np.array(joints[6])  # 投球側肩
        elbow = np.array(joints[8])     # 肘
        wrist = np.array(joints[10])    # 手腕
        neck = np.array(joints[18])      # 頸
        hip = np.array(joints[19])       # 臀

        # 上臂與前臂向量
        upper = shoulder - elbow
        forearm = wrist - elbow

        # 前臂與上臂形成的平面法向量
        plane_normal = np.cross(upper, forearm)
        if np.linalg.norm(plane_normal) == 0:
            print("Vectors are collinear; cannot define plane.")
            return 0.0
        plane_normal /= np.linalg.norm(plane_normal)

        # XZ 平面法向量 (y軸方向)
        y_axis = hip - neck
        y_axis /= np.linalg.norm(y_axis)

        # 計算夾角
        dot_val = np.clip(np.dot(plane_normal, y_axis), -1.0, 1.0)
        angle = np.degrees(np.arccos(dot_val))

        # print(f"前臂-上臂平面與XZ平面夾角: {angle:.2f} 度")
        return int(angle)
    
    def calculate_angle_between_shoulder_hip_lines(self, frame_idx=None):
        if not self.all_3d_frames:
            print("No 3D frames available.")
            return 0.0

        joints = self.all_3d_frames[frame_idx]
        left_shoulder = np.array(joints[5])
        right_shoulder = np.array(joints[6])
        left_hip = np.array(joints[11])
        right_hip = np.array(joints[12])

        shoulder_line = right_shoulder - left_shoulder
        hip_line = right_hip - left_hip

        shoulder_vector_xz = np.array([shoulder_line[0], shoulder_line[2]])
        hip_vector_xz = np.array([hip_line[0], hip_line[2]])

        magnitude_shoulder = np.linalg.norm(shoulder_vector_xz)
        magnitude_hip = np.linalg.norm(hip_vector_xz)

        if magnitude_shoulder == 0 or magnitude_hip == 0:
            print("One of the lines has zero length; cannot compute angle.")
            return 0.0

        dot_val = np.dot(shoulder_vector_xz, hip_vector_xz) / (magnitude_shoulder * magnitude_hip)

        dot_val = np.clip(dot_val, -1.0, 1.0)
        angle = np.degrees(np.arccos(dot_val))

        # print(f"肩線與臀線夾角: {angle:.2f} 度")
        return int(angle)

    def calculate_angle_between_shoulder_hip_lines_signed(self, frame_idx=None):
        if not self.all_3d_frames:
            print("No 3D frames available.")
            return 0.0

        joints = self.all_3d_frames[frame_idx]
        left_shoulder = np.array(joints[5])
        right_shoulder = np.array(joints[6])
        left_hip = np.array(joints[11])
        right_hip = np.array(joints[12])

        # 向量：左→右
        shoulder_line = right_shoulder - left_shoulder
        hip_line = right_hip - left_hip

        # 投影到水平平面 xz
        shoulder_vec = np.array([shoulder_line[0], shoulder_line[2]])
        hip_vec = np.array([hip_line[0], hip_line[2]])

        # 長度檢查
        if np.linalg.norm(shoulder_vec) == 0 or np.linalg.norm(hip_vec) == 0:
            print("One of the lines has zero length; cannot compute angle.")
            return 0.0

        # dot 與 det（叉積標量）
        dot = np.dot(hip_vec, shoulder_vec)
        det = hip_vec[0] * shoulder_vec[1] - hip_vec[1] * shoulder_vec[0]

        # atan2(det, dot) → signed angle (-180~180)
        angle = np.degrees(np.arctan2(det, dot))
        angle = -angle

        # ---------------------------------------------------
        # 若你希望「肩在髖後方時 → 角度為正」但結果相反，
        # 只需翻轉符號：
        # angle = -angle
        # ---------------------------------------------------

        return int(angle)


    def compute_joint_velocity(self, joint_idx, delta_t, frame_idx=None):
        """
        計算指定 joint_idx 在 all_3d_frames 中所有幀的速度，使用中心差分法。

        回傳一個 shape=(frame_num, 3) 的速度向量陣列。
        """
        sorted_keys = sorted(self.all_3d_frames.keys())
        frames_list = [self.all_3d_frames[k] for k in sorted_keys]
        frames = np.array(frames_list)  # shape = (N, 26, 3)
        n_frames = len(frames)
        if n_frames < 2:
            print("Frame數量太少，無法計算速度")
            return np.zeros(n_frames)
        if joint_idx < 0 or joint_idx >= frames.shape[1]:
            print("關節索引超出範圍")
            return None
        
        # --- 取出單一關節座標 (frame_num, 3) ---
        joint_positions = frames[:, joint_idx, :]

        # --- 平滑 (確保 window 長度 <= n_frames 且為奇數) ---
        window = min(5, n_frames if n_frames % 2 == 1 else n_frames - 1)
        if window >= 3:
            smoothed = savgol_filter(joint_positions, window_length=window, polyorder=2, axis=0)
        else:
            smoothed = joint_positions  # 如果 frame 太少就直接用原始值

        velocities = np.zeros((n_frames, 3))

        # 中心差分
        velocities[1:-1] = (smoothed[2:] - smoothed[:-2]) / (2 * delta_t)
        # 邊界點
        velocities[0] = (smoothed[1] - smoothed[0]) / delta_t
        velocities[-1] = (smoothed[-1] - smoothed[-2]) / delta_t
        speeds = np.linalg.norm(velocities, axis=1)  # shape = (frame_num,)
        real_speeds = speeds * 29.24  # 將速度轉換為m/s

        if frame_idx is not None:
            if frame_idx in sorted_keys:
                # 找出該 frame_idx 在陣列中的真實索引位置 (0 ~ N-1)
                array_idx = sorted_keys.index(frame_idx)
                return float(real_speeds[array_idx])
            else:
                return 0.0
        return real_speeds

    def compute_joint_velocity_causal(self, joint_idx, delta_t, frame_idx=None, ema_alpha=0.3, window=5):
        """
        單邊(因果)速度估計：只用當前與過去幀，適用即時分析。

        - 位置平滑：使用過去 window 幀的簡單移動平均；若 window=1 則不平滑。
        - 速度估計：前向差分 v[i] = (p[i] - p[i-1]) / dt，首幀速度為 0。
        - 可選 EMA 平滑速度，ema_alpha 越小越平滑；設為 None 代表不做 EMA。

        參數：
            joint_idx: 關節索引 (0-25)
            delta_t: 幀時間 (秒)
            frame_idx: 若提供，回傳該幀速度，否則回傳全序列
            ema_alpha: 指數平滑係數，0<alpha<=1；None 表示不平滑
            window: 移動平均窗口，用於位置平滑 (>=1)
        """
        # 性能優化：使用緩存避免重複計算
        cache_key = (joint_idx, delta_t, ema_alpha, window)
        if not hasattr(self, '_velocity_cache'):
            self._velocity_cache = {}
        
        sorted_keys = sorted(self.all_3d_frames.keys())
        
        # 如果只查詢單幀且已緩存，直接返回
        if frame_idx is not None and cache_key in self._velocity_cache:
            cached_speeds = self._velocity_cache[cache_key]
            if frame_idx in sorted_keys and len(cached_speeds) >= len(sorted_keys):
                array_idx = sorted_keys.index(frame_idx)
                if array_idx < len(cached_speeds):
                    return float(cached_speeds[array_idx])
        
        frames_list = [self.all_3d_frames[k] for k in sorted_keys]
        frames = np.array(frames_list)  # shape = (N, 26, 3)
        n_frames = len(frames)
        if n_frames < 2:
            return 0.0 if frame_idx is not None else np.zeros(n_frames)
        if joint_idx < 0 or joint_idx >= frames.shape[1]:
            return None

        # 位置平滑：僅用過去窗口
        window = max(1, window)
        smoothed = np.zeros((n_frames, 3))
        for i in range(n_frames):
            start = max(0, i - window + 1)
            smoothed[i] = frames[start:i+1, joint_idx, :].mean(axis=0)

        velocities = np.zeros((n_frames, 3))
        velocities[0] = 0.0
        velocities[1:] = (smoothed[1:] - smoothed[:-1]) / delta_t

        # 速度 EMA 平滑 (可選)
        if ema_alpha is not None:
            ema = np.zeros_like(velocities)
            ema[0] = velocities[0]
            for i in range(1, n_frames):
                ema[i] = ema_alpha * velocities[i] + (1 - ema_alpha) * ema[i-1]
            velocities = ema

        speeds = np.linalg.norm(velocities, axis=1)
        # real_speeds = speeds * 29.24  # 轉 m/s
        # real_speeds = speeds * 26.24  # 轉 m/s
        real_speeds = speeds * 21.56  # 轉 m/s
        
        # 緩存結果
        self._velocity_cache[cache_key] = real_speeds

        if frame_idx is not None:
            if frame_idx in sorted_keys:
                array_idx = sorted_keys.index(frame_idx)
                return float(real_speeds[array_idx])
            return 0.0
        return real_speeds

